  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Places the head pipe from the queue at the location selected by
   *          the player, expressed as a row number and a column letter. The
   *          step counter is incremented on a successful placement.
   * Algorithm:
   *   1. Translate the player-supplied column letter to an internal column
   *      index: colIndex = col - 'A' + 1.
   *   2. Obtain the head pipe by calling pipeQueue.peek().
   *   3. Invoke map.tryPlacePipe(row, colIndex, headPipe).
   *   4. If placement succeeds:
   *        a. Push the affected FillableCell onto cellStack so it can be undone.
   *        b. Advance the queue by calling pipeQueue.consume().
   *        c. Increment numOfSteps.
   *        d. Return true.
   *   5. Otherwise, return false (invalid coordinates or occupied cell).
   * Related Features: numOfSteps : int, cellStack : CellStack, pipeQueue : PipeQueue,
   *                   map : Map.
   * Related Classes: Map, PipeQueue, CellStack, FillableCell, Pipe.
   * Input:
   *   row : int — the player-facing row number in [1, rows-2] (playable range).
   *   col : char — a column letter from 'A'..(A + cols-3) inclusive; mapped to
   *                [1, cols-2] via col - 'A' + 1.
   * Output: boolean — true if the pipe was placed successfully, false if the
   *         target cell is out of range or already occupied.
   * Pre-condition: The row is within the playable range; the column letter is a
   *                valid map character; the queue is non-empty.
   * Post-condition: On success, the head pipe is consumed from the queue, the
   *                cell contains the pipe, cellStack records the placement, and
   *                numOfSteps is increased by 1. On failure, no state changes.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean placePipe(final int row, final char col)
  {
    final int colIndex = col - 'A' + 1;
    final Pipe headPipe = getPipeQueue().peek();
    final boolean placed = getMap().tryPlacePipe(row, colIndex, headPipe);
    if (placed)
    {
      getCellStack().push((FillableCell) getMap().getCell()[row][colIndex]);
      getPipeQueue().consume();
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }
    return false;
  }

